                            <button onClick={() => removeHeroImage(url)} className="absolute bottom-1.5 right-1.5 px-2 py-1 rounded-lg text-[10.5px] font-semibold" style={{ background: 'rgba(0,0,0,0.65)', color: '#fff' }}>Remove</button>
