                    <div className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0" style={{ background: b.tone === 'copper' ? C.copper : C.surface }}><Sparkles size={18} style={{ color: b.tone === 'copper' ? C.bg : C.copper }} /></div>
